@startuml

class Doctor {
  + PractitionerNumber : int
  + FullName : string
  + Address : string
  + PhoneNumber : string
  + Signature : string
}

class Patient {
  + HealthNumber : string
  + FirstName : string
  + LastName : string
  + DateOfBirth : date
  + Address : string
  + PhoneNumber : string
}

class Requisition {
  + ValidFrom : date
  + RepetitionCount : int
  + RepetitionInterval : Interval
}

enum Interval {
  WEEKLY
  MONTHLY
  HALF_YEARLY
  YEARLY
}

class Test {
  + Name : string
  + Duration : int
  + RequiresAppointment : boolean
  + RequiresSampleDropOff : boolean
}

class TestGroup {
  + GroupName : string
}

class TestResult {
  + IsPositive : boolean
  + Report : string
}

class Lab {
  + Address : string
  + RegistrationNumber : string
  + BusinessHoursStart : time
  + BusinessHoursEnd : time
  + CancellationFee : float
}

class Appointment {
  + ConfirmationNumber : string
  + Date : date
  + StartTime : time
  + EndTime : time
}

Doctor "1" -- "*" Requisition : prescribes
Patient "1" -- "*" Requisition : is subject of
Requisition "1" *-- "1..*" Test : contains
Test "*" -- "1" TestGroup : belongs to
Test "1" -- "0..*" TestResult : has
TestResult "0..*" -- "1" Doctor : views
TestResult "0..*" -- "1" Patient : views
Patient "1" -- "*" Appointment : books
Appointment "1" -- "1" Lab : at
Appointment "1" -- "1" Requisition : for
Appointment "1" -- "1" Test : for
Lab "1" -- "*" Test : offers

@enduml

